import{_ as n,I as l,o as s,c as d,j as a,a as t,J as i,ak as r}from"./chunks/framework.D6lxc04_.js";const f=JSON.parse('{"title":"Moveable Entity Block","description":"","frontmatter":{"title":"Moveable Entity Block","prev":false,"next":false},"headers":[],"relativePath":"en/posts/docs/moveable-entity-block/index.md","filePath":"en/posts/docs/moveable-entity-block/index.md","lastUpdated":1778164094000}'),c={name:"en/posts/docs/moveable-entity-block/index.md"},h={id:"moveable-entity-block-module",tabindex:"-1"};function m(p,e,b,v,u,y){const o=l("Badge");return s(),d("div",null,[a("h1",h,[e[0]||(e[0]=t("Moveable Entity Block Module ",-1)),i(o,{type:"tip",text:">=1.21.1"}),e[1]||(e[1]=t()),i(o,{type:"danger",text:"API redesigned in 26.1"}),e[2]||(e[2]=t()),e[3]||(e[3]=a("a",{class:"header-anchor",href:"#moveable-entity-block-module","aria-label":"Permalink to “Moveable Entity Block Module”"},"​",-1))]),e[4]||(e[4]=r('<p>The package <code>dev.anvilcraft.lib.v2.piston</code> solves the issue of vanilla pistons being unable to push blocks with block entities. Through a set of Mixins and interfaces, it allows blocks to carry custom NBT data during movement and write the data back to the block entity at the destination when the piston stops.</p><h2 id="document-index" tabindex="-1">Document Index <a class="header-anchor" href="#document-index" aria-label="Permalink to “Document Index”">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Content</th></tr></thead><tbody><tr><td><a href="./api.html">Core Interfaces</a></td><td><code>IMoveableEntityBlock</code>, <code>IPistonMovingBlockEntityExtension</code></td></tr><tr><td><a href="./usage.html">Mixin and Usage</a></td><td>Mixin modification points, complete usage example</td></tr></tbody></table><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>In vanilla, a piston pushing a block with a block entity has no effect. This module injects into the piston movement logic:</p><ol><li><strong>Before movement</strong> -- Calls <code>clearData</code> to extract block entity data</li><li><strong>During movement</strong> -- Data is temporarily stored in <code>PistonMovingBlockEntity</code></li><li><strong>After movement</strong> -- Calls <code>setData</code> to write data back to the block entity at the new position</li></ol><p>The entire process is transparent to the server and requires no modification to the vanilla piston core logic.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>All data transfer occurs server-side; the client does not retain additional data</li><li><code>clearData</code> should return only the custom data that needs to be preserved, not serialize the entire block entity</li><li><code>IMoveableEntityBlock</code> extends <code>EntityBlock</code>; if your block is already a <code>BaseEntityBlock</code> subclass, you only need to additionally implement this interface</li><li>Mixin priority is <code>priority = 943</code>; may need adjustment if conflicting with other piston-modifying mods</li></ul>',9))])}const x=n(c,[["render",m]]);export{f as __pageData,x as default};
